function getPlayerAuctionCost(player) {
    if (!player) return 1;
    const cleanN = player.name.toLowerCase().trim();
    if (REAL_AUCTION_PRICES[cleanN] !== undefined) {
        return REAL_AUCTION_PRICES[cleanN];
    }
    return player.prezzo_cons || 1;
}
